def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def digest(x):return hashlib.sha256(json.dumps(x,sort_keys=True,ensure_ascii=False,separators=(',',':'),allow_nan=False).encode()).hexdigest()
def read(p):return json.loads(Path(p).read_text())
def write(name,x):(OUT/name).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
def pointer(x,p):
 for k in p.split('/')[1:]:x=x[int(k)] if isinstance(x,list) else x[k.replace('~1','/').replace('~0','~')]
 return x

def binding(p,ptr=''):return dict(path=p,sha256=sha(ROOT/p),jsonPointer=ptr,objectHash=digest(pointer(read(ROOT/p),ptr)))
def hyp(value,unit,name,rationale,lo=None,hi=None):return dict(value=value,unit=unit,classification='HYPOTHETICAL_ASSUMPTION',rationale=rationale,evidenceStatus='ILLUSTRATIVE_NOT_EMPIRICALLY_QUALIFIED_FORECAST',ownerApprovalStatus='SANDBOX_SCOPE_ONLY_NOT_NUMERICAL_ECONOMICS_APPROVED',sensitivityRange=dict(min=lo,max=hi,meaning='Illustrative exploration interval, not a qualified economic bound'),applicableScenario=name)
